import{V as e,ht as t,nt as n,tt as r}from"./chunks/framework.wxcks8ca.js";var i=JSON.parse(`{"title":"从 kimi-cli 迁移","description":"","frontmatter":{},"headers":[],"relativePath":"kimi-code-cli/guides/migration.md","filePath":"zh/kimi-code-cli/guides/migration.md"}`),a={name:`kimi-code-cli/guides/migration.md`};function o(e,i,a,o,s,c){return t(),r(`div`,null,[...i[0]||=[n(`<h1 id="从-kimi-cli-迁移" tabindex="-1">从 kimi-cli 迁移 <a class="header-anchor" href="#从-kimi-cli-迁移" aria-label="Permalink to “从 kimi-cli 迁移”">​</a></h1><div class="info custom-block"><p class="custom-block-title custom-block-title-default">INFO</p><p>Kimi Code CLI 已完成重大版本升级，底层从 Python/uv 迁移至 Node.js，带来更简单的安装方式、更快的启动速度和全新的终端界面。旧版将逐渐停止维护，建议尽快升级至新版。</p></div><p>如果你正在从旧版迁移，按照以下步骤操作——一条命令就能把配置、MCP server 与会话历史一并迁移至新版。</p><h2 id="新版优势" tabindex="-1">新版优势 <a class="header-anchor" href="#新版优势" aria-label="Permalink to “新版优势”">​</a></h2><ul><li><strong>不再依赖 Python / uv</strong>：基于 Node.js 重写，无需配置 Python 环境，安装更简单</li><li><strong>原生二进制，开箱即用</strong>：启动更快，运行更轻量</li><li><strong>终端界面全面重设计</strong>：交互体验更流畅</li><li><strong>数据可完整迁移</strong>：配置、MCP、会话历史一键带走，无缝延续</li></ul><h2 id="如何迁移" tabindex="-1">如何迁移 <a class="header-anchor" href="#如何迁移" aria-label="Permalink to “如何迁移”">​</a></h2><p>迁移有两种方式。</p><p>装好 kimi-code 之后<strong>第一次运行 <code>kimi</code></strong> 时，它会自动检测 <code>~/.kimi/</code> 下是否存在 kimi-cli 的数据。一旦检测到，就会弹出迁移提示，你可以选择立即迁移、稍后再说，或不再提示。</p><p>你也可以<strong>随时手动运行</strong>：</p><div class="language-sh"><button title="Copy Code" class="copy"></button><span class="lang">sh</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">kimi</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> migrate</span></span></code></pre></div><p>你可以选择是否同时迁移聊天会话。如果暂时不需要历史记录，选 <strong>Config only</strong>；否则选 <strong>Config + N sessions</strong> 一并迁移。结束后会显示结果摘要。</p><h2 id="迁移会发生什么" tabindex="-1">迁移会发生什么 <a class="header-anchor" href="#迁移会发生什么" aria-label="Permalink to “迁移会发生什么”">​</a></h2><p><strong>会被迁移的内容</strong>：配置（<code>config.toml</code>）、MCP 服务配置、输入历史，以及你选择迁移的聊天会话。</p><p><strong>不会被迁移的内容</strong>：OAuth 登录凭证和 MCP 服务的授权都不会被复制，迁移后需要在 kimi-code 里重新执行 <code>/login</code> 和重新授权 MCP 服务。kimi-cli 的插件也不在迁移范围内。</p><div class="tip custom-block"><p class="custom-block-title">提示</p><p>迁移<strong>不会改动或删除</strong> <code>~/.kimi/</code> 下的任何旧数据。kimi-cli 仍可照常使用，两者互不影响。迁移也可以重复运行，已经迁移过的会话不会被重复导入。</p></div><p>迁移完成后，从 kimi-cli 导入的会话会带上 <code>[imported]</code> 标记，方便你与新建的会话区分。</p>`,16)]])}var s=e(a,[[`render`,o]]);export{i as __pageData,s as default};